    ADD CONSTRAINT media_purge_follows_delete CHECK (((purged_at IS NULL) OR ((status = 'deleted'::public.media_status) AND (deleted_at IS NOT NULL) AND (purged_at >= (deleted_at + '30 days'::interval))))) NOT VALID;


--
-- Name: media media_ready_is_inspected; Type: CHECK CONSTRAINT; Schema: public; Owner: cms_migration_owner
--

ALTER TABLE public.media
    ADD CONSTRAINT media_ready_is_inspected CHECK (((status <> 'ready'::public.media_status) OR ((content_hash ~ '^[0-9a-f]{64}$'::text) AND (mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text])) AND ((bytes >= 1) AND (bytes <= 26214400)) AND ((width >= 1) AND (width <= 32768)) AND ((height >= 1) AND (height <= 32768)) AND (((width)::bigint * (height)::bigint) <= 100000000) AND (deleted_at IS NULL)))) NOT VALID;


