CREATE POLICY comments_member_read ON public.comments FOR SELECT TO cms_authenticated_user USING (((app.has_site_access(site_id) OR ((item_type = 'page'::public.reviewable_type) AND app.has_page_access(item_id))) AND ((author_id = app.current_user_id()) OR ((item_type = 'page'::public.reviewable_type) AND app.can_publish_page(item_id)) OR app.can_review(site_id) OR (EXISTS ( SELECT 1
   FROM public.submissions s
  WHERE ((s.site_id = comments.site_id) AND (s.item_type = comments.item_type) AND (s.item_id = comments.item_id) AND (NOT (s.version_id IS DISTINCT FROM comments.version_id)) AND (s.submitted_by = app.current_user_id())))))));


--
-- Name: comments comments_member_resolve; Type: POLICY; Schema: public; Owner: cms_migration_owner
--

CREATE POLICY comments_member_resolve ON public.comments FOR UPDATE TO cms_authenticated_user USING (app.has_site_access(site_id)) WITH CHECK (app.has_site_access(site_id));


