--
-- Name: sites sites_member; Type: POLICY; Schema: public; Owner: cms_migration_owner
--

CREATE POLICY sites_member ON public.sites FOR SELECT TO cms_authenticated_user USING ((app.has_site_access(id) OR app.has_scoped_site_access(id)));


--
-- Name: sites sites_worker; Type: POLICY; Schema: public; Owner: cms_migration_owner
--

CREATE POLICY sites_worker ON public.sites FOR SELECT TO cms_worker USING (true);


--
-- Name: story_draft_receipts; Type: ROW SECURITY; Schema: public; Owner: cms_migration_owner
--

ALTER TABLE public.story_draft_receipts ENABLE ROW LEVEL SECURITY;

--
-- Name: story_draft_receipts story_draft_receipts_author; Type: POLICY; Schema: public; Owner: cms_migration_owner
--

CREATE POLICY story_draft_receipts_author ON public.story_draft_receipts FOR SELECT TO cms_authenticated_user USING (((created_by = app.current_user_id()) AND app.has_site_access(site_id)));


--
-- Name: story_review_pins; Type: ROW SECURITY; Schema: public; Owner: cms_migration_owner
--

ALTER TABLE public.story_review_pins ENABLE ROW LEVEL SECURITY;

--
-- Name: story_review_pins story_review_pins_visible; Type: POLICY; Schema: public; Owner: cms_migration_owner
--

CREATE POLICY story_review_pins_visible ON public.story_review_pins FOR SELECT TO cms_authenticated_user USING ((EXISTS ( SELECT 1
   FROM public.submissions s
  WHERE ((s.id = story_review_pins.submission_id) AND app.has_site_access(s.site_id) AND ((s.submitted_by = app.current_user_id()) OR app.can_review(s.site_id))))));


